  "generation.error.unsupportedSettings": { en: "The current generation setup cannot use one of the enabled options yet. Turn off unavailable runtime options and try again.", ja: "現在の生成環境では、有効になっている一部の設定をまだ使えません。利用できないランタイム設定をオフにして再試行してください。" },
  "generation.error.inpaintSourceUnavailable": { en: "The source image could not be read. Re-upload the source image and try again.", ja: "元画像を読み込めませんでした。元画像を再アップロードしてから再試行してください。" },
  "generation.error.inpaintMaskUnavailable": { en: "The mask image could not be read. Re-create or re-upload the mask and try again.", ja: "マスク画像を読み込めませんでした。マスクを作り直すか再アップロードしてから再試行してください。" },
  "generation.error.inpaintSizeMismatch": { en: "The source image and mask must have the same dimensions.", ja: "元画像とマスク画像のサイズを同じにしてください。" },
  "generation.error.inpaintEmptyMask": { en: "The mask is empty. Paint the area to change and try again.", ja: "マスクが空です。変更する範囲を塗ってから再試行してください。" },
  "generation.error.inpaintGeometryInvalid": { en: "The masked area could not be prepared. Use an image between 256 and 4096 pixels and try again.", ja: "マスク範囲を準備できませんでした。256～4096pxの画像を使用して再試行してください。" },
  "generation.error.missingRuntimeModel": { en: "A selected model is not available in the current generation setup. Refresh generation assets or choose another model, then try again.", ja: "選択中のモデルを現在の生成環境で使えません。生成アセットを更新するか、別のモデルを選んでから再試行してください。" },
  "generation.error.missingGenerationImageInput": { en: "Choose an input image for this image mode, then try again.", ja: "この画像モードで使う入力画像を選んでから再試行してください。" },
  "generation.error.missingControlNetImage": { en: "Choose a ControlNet image or turn off the ControlNet unit, then try again.", ja: "ControlNet画像を選ぶか、ControlNetユニットをオフにしてから再試行してください。" },
  "generation.error.missingControlNetModel": { en: "Choose an installed ControlNet model or refresh generation assets, then try again.", ja: "インストール済みのControlNetモデルを選ぶか、生成アセットを更新してから再試行してください。" },
  "generation.error.unsupportedControlNetPreprocessor": { en: "The selected ControlNet preprocessor is not available. Choose another preprocessor and try again.", ja: "選択中のControlNet前処理は使えません。別の前処理を選んで再試行してください。" },
  "generation.error.missingAnimaLLLiteRuntime": { en: "Install the Anima LLLite runtime node, restart the generation setup, then try again.", ja: "Anima LLLiteの実行ノードをインストールし、生成環境を再起動してから再試行してください。" },
  "generation.error.missingAnimaRegionalRuntime": { en: "Install the Anima regional prompting runtime node, restart the generation setup, then try again.", ja: "Anima Regional Promptingの実行ノードをインストールし、生成環境を再起動してから再試行してください。" },
  "generation.error.missingAnimaLLLiteImage": { en: "Choose an Anima LLLite control image or turn off the unit, then try again.", ja: "Anima LLLiteの制御画像を選ぶか、ユニットをオフにしてから再試行してください。" },
  "generation.error.missingAnimaLLLiteModel": { en: "Choose an installed Anima LLLite model or refresh generation assets, then try again.", ja: "インストール済みのAnima LLLiteモデルを選ぶか、生成アセットを更新してから再試行してください。" },
  "generation.error.missingDetailerDetector": { en: "Choose an installed Detailer detector or refresh generation assets, then try again.", ja: "インストール済みのDetailer検出モデルを選ぶか、生成アセットを更新してから再試行してください。" },
  "generation.error.missingLoraModel": { en: "Choose an installed LoRA or refresh generation assets, then try again.", ja: "インストール済みのLoRAを選ぶか、生成アセットを更新してから再試行してください。" },
  "generation.error.unsupportedSampling": { en: "The selected sampler, scheduler, or Hires override is not available in the current generation setup. Choose another option and try again.", ja: "選択中のSampler、Scheduler、またはHires上書き設定は現在の生成環境で使えません。別の項目を選んで再試行してください。" },
  "generation.error.missingHiresUpscaler": { en: "The selected Hires upscaler model is not available. Refresh assets or choose another upscaler and try again.", ja: "選択中のHires upscalerモデルが見つかりません。アセットを再読み込みするか、別のupscalerを選んで再試行してください。" },
  "generation.error.xyzPlotInvalid": { en: "Review the XYZ Plot axes and values, then try again.", ja: "XYZ Plotの軸と値を確認してから再試行してください。" },
  "generation.error.missingModelSelection": { en: "A required model is not selected. Choose the required model assets and try again.", ja: "必要なモデルが選択されていません。必要なモデルアセットを選んで再試行してください。" },
  "generation.error.missingModelFile": { en: "A selected model file cannot be found. Refresh assets or choose another model and try again.", ja: "選択中のモデルファイルが見つかりません。アセットを再読み込みするか、別のモデルを選んで再試行してください。" },
  "generation.error.unsupportedImageMode": { en: "The selected model profile does not support this image mode yet. Switch profile or generation mode and try again.", ja: "選択中のモデルプロファイルでは、この画像モードをまだ使えません。プロファイルまたは生成モードを切り替えて再試行してください。" },
  "generation.error.profileUnavailable": { en: "The selected model profile is not available. Choose another profile or refresh generation assets.", ja: "選択中のモデルプロファイルを使えません。別のプロファイルを選ぶか、生成アセットを更新してください。" },
  "generation.error.schemaUnavailable": { en: "Could not load the generation settings for this profile. Refresh generation assets or choose another profile.", ja: "このプロファイルの生成設定を読み込めませんでした。生成アセットを更新するか、別のプロファイルを選んでください。" },
  "generation.error.promptPresetPromptRequired": { en: "Enter a prompt before saving it as a preset.", ja: "プリセットとして保存する前にプロンプトを入力してください。" },
  "generation.error.promptPresetSave": { en: "Could not save the prompt preset. Review the prompt and try again.", ja: "プロンプトプリセットを保存できませんでした。プロンプトを確認してから再試行してください。" },
  "generation.error.studioPresetInvalid": { en: "Choose a supported preset type and try again.", ja: "対応しているプリセット種別を選んでから再試行してください。" },
  "generation.error.studioPresetSave": { en: "Could not save the generation preset. Review the preset name and settings, then try again.", ja: "生成プリセットを保存できませんでした。プリセット名と設定を確認してから再試行してください。" },
