    async runCopyMachineComparison(input) {
      this.saving = true;
      this.error = "";
      this.message = "";
      try {
        const result = await $fetch("/api/lora-training/copy-machine/comparisons/run", {
          baseURL: useApiBase(),
          method: "POST",
          body: {
            run_id: input.run_id,
            prompt: input.prompt,
            negative_prompt: input.negative_prompt ?? "",
            seed: input.seed ?? 1,
            width: input.width ?? 1024,
            height: input.height ?? 1024,
            positive_strength: input.positive_strength ?? 1
          }
        });
        this.copyMachineComparisonResult = result;
        this.copyMachineComparisonPlan = {
          run_id: result.run_id,
          status: result.status === "completed" ? "planned" : "blocked",
          generation_requests: result.cells.map((cell) => ({
            label: cell.labels.variant ?? `image_${cell.index + 1}`,
            prompt: cell.generation.prompt,
            negative_prompt: cell.generation.negative_prompt,
            seed: Number(cell.generation.settings.seed ?? input.seed ?? 1),
            width: Number(cell.generation.settings.width ?? input.width ?? 1024),
            height: Number(cell.generation.settings.height ?? input.height ?? 1024),
            loras: cell.generation.loras.map((lora) => ({ path: lora.name, strength: lora.weight }))
          })),
          warnings: result.warnings,
          errors: result.errors
        };
        this.message = result.status === "completed" ? messageText("lora.message.copyMachineComparisonCompleted", { count: result.cells.length, plural: result.cells.length === 1 ? "" : "s" }) : messageText("lora.message.copyMachineComparisonNeedsAttention");
        if (result.warnings.length) {
          this.message += ` ${result.warnings.map(copyMachineComparisonWarningMessage).join(" ")}`;
        }
        return result;
      } catch (error) {
        this.error = errorMessage(error, "lora.error.runCopyMachineComparison");
        return null;
      } finally {
        this.saving = false;
      }
    },
